function repeatableFields(prefix: string, count: number, options: { omitFirstName?: boolean } = {}): string[] {
  return Array.from({ length: count }, (_, index) => {
    const row = index + 1;
    return [
      ...options.omitFirstName && row === 1 ? [] : [`${prefix}_${row}_name`],
      `${prefix}_${row}_joint`,
      `${prefix}_${row}_a`,
      `${prefix}_${row}_b`,
      `${prefix}_${row}_notes`,
    ];
  }).flat();
}

